MOD = 10**9 + 7

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_confusing_sets(n, a):
    parent = list(range(n))
    rank = [0] * n

    for i in range(n):
        union(parent, rank, i, a[i] - 1)

    cycle_count = len(set(find(parent, i) for i in range(n)))

    return pow(2, cycle_count, MOD)

